const data = $json;

let result = data.output;

if (typeof result !== "string") {
  result = JSON.stringify(result);
}

result = result
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(result);
} catch (error) {
  throw new Error("Invalid JSON returned by AI");
}

return {
  json: {
    ...data,
    ...parsed
  }
};

const items = $input.all();

const requiredFields = [
  "Complaint_ID",
  "Customer_ID",
  "Customer_Name",
  "Customer_Email",
  "Complaint",
  "Category",
  "Date_Received",
  "Previous_Complaints"
];

const validItems = [];
const invalidItems = [];

for (const item of items) {

  const data = item.json;

  const missingFields = requiredFields.filter(
    field =>
      data[field] === undefined ||
      data[field] === null ||
      String(data[field]).trim() === ""
  );

  const previousComplaints =
    Number(data.Previous_Complaints);

  if (
    missingFields.length === 0 &&
    !isNaN(previousComplaints) &&
    previousComplaints >= 0
  ) {

    validItems.push({
      ...data,
      Previous_Complaints: previousComplaints
    });

  } else {

    invalidItems.push({
      complaint_id:
        data.Complaint_ID || "Unknown",

      missing_fields:
        missingFields
    });

  }
}

return [
  {
    json: {
      data_valid:
        invalidItems.length === 0,

      total_complaints:
        items.length,

      valid_complaints:
        validItems.length,

      invalid_complaints:
        invalidItems.length,

      invalid_details:
        invalidItems,

      complaint_data:
        validItems
    }
  }
];

const data = $json.complaint_data;

const analyzedComplaints = [];

for (const complaint of data) {

  const priority =
    String(complaint.Category || "").toLowerCase();

  const previousComplaints =
    Number(complaint.Previous_Complaints);

  let initialScore = 0;

  // Repeated complaints
  if (previousComplaints >= 3) {
    initialScore += 3;
  } else if (previousComplaints >= 1) {
    initialScore += 1;
  }

  // Category-based signals
  if (
    priority === "billing" ||
    priority === "payment"
  ) {
    initialScore += 2;
  }

  if (
    priority === "technical" ||
    priority === "account"
  ) {
    initialScore += 2;
  }

  let initialPriority;

  if (initialScore >= 5) {
    initialPriority = "HIGH";
  } else if (initialScore >= 3) {
    initialPriority = "MEDIUM";
  } else {
    initialPriority = "LOW";
  }

  analyzedComplaints.push({
    ...complaint,
    initial_score: initialScore,
    initial_priority: initialPriority
  });
}

return [
  {
    json: {
      analyzed_complaints:
        analyzedComplaints
    }
  }
];

